:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --accent: #6c5ce7;
  --accent-hover: #5a4bd1;
  --success: #00b894;
  --error: #e17055;
  --border: #3d3d5c;
  --focus: #a29bfe;
  font-size: 16px;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  min-height: 100vh;
  padding: 1.5rem 1rem;
}

.card {
  background: var(--card-bg);
  border-radius: 1rem;
  padding: 2rem 1.5rem;
  width: 100%;
  max-width: 600px;
  box-shadow: 0 8px 24px rgba(0,0,0,0.4);
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 1.5rem;
  text-align: center;
}

h2 {
  font-size: 1.25rem;
  margin-bottom: 0.75rem;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.add-form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

label {
  font-weight: 600;
  font-size: 0.95rem;
}

input {
  padding: 0.6rem 0.75rem;
  border-radius: 0.5rem;
  border: 1px solid var(--border);
  background: var(--bg);
  color: var(--text);
  font-size: 1rem;
  font-family: inherit;
  transition: border-color 0.2s, box-shadow 0.2s;
}

input:focus {
  outline: none;
  border-color: var(--focus);
  box-shadow: 0 0 0 3px rgba(162, 155, 254, 0.3);
}

.btn {
  padding: 0.6rem 1.2rem;
  border: none;
  border-radius: 0.5rem;
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  background: var(--accent);
  color: #fff;
}

.btn:hover {
  background: var(--accent-hover);
}

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn.primary {
  background: var(--accent);
}

.btn.primary:hover {
  background: var(--accent-hover);
}

.btn.log-btn {
  background: var(--success);
  padding: 0.4rem 0.8rem;
  font-size: 0.9rem;
}

.btn.log-btn:hover {
  background: #00a383;
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.error {
  color: var(--error);
  font-size: 0.9rem;
  min-height: 1.2rem;
  margin-bottom: 0.5rem;
}

.empty {
  text-align: center;
  color: #a0a0b8;
  font-style: italic;
  margin-top: 1rem;
}

.books-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.book-item {
  background: var(--bg);
  border-radius: 0.75rem;
  padding: 1rem;
  border: 1px solid var(--border);
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.book-header {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.book-title {
  font-weight: 700;
  font-size: 1.1rem;
  word-break: break-word;
}

.book-pages {
  font-size: 0.9rem;
  color: #a0a0b8;
}

.progress-container {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.progress-bar-wrapper {
  flex: 1;
  height: 0.75rem;
  background: var(--border);
  border-radius: 999px;
  overflow: hidden;
}

.progress-bar {
  height: 100%;
  width: 0%;
  background: var(--accent);
  border-radius: 999px;
  transition: width 0.3s ease;
}

.progress-bar.finished {
  background: var(--success);
}

.progress-text {
  font-size: 0.9rem;
  font-weight: 600;
  min-width: 3.5rem;
  text-align: right;
}

.log-form {
  display: flex;
  gap: 0.5rem;
  align-items: center;
  flex-wrap: wrap;
}

.log-form label {
  font-size: 0.9rem;
  font-weight: 500;
}

.log-form input {
  width: 5rem;
  padding: 0.4rem 0.5rem;
  font-size: 0.9rem;
}

.finished-badge {
  color: var(--success);
  font-weight: 700;
  font-size: 0.9rem;
}

@media (max-width: 400px) {
  .card {
    padding: 1.25rem 1rem;
  }
  h1 {
    font-size: 1.4rem;
  }
  .log-form {
    flex-direction: column;
    align-items: stretch;
  }
  .log-form input {
    width: 100%;
  }
}

(function() {
  'use strict';

  const books = [];
  let nextId = 1;

  const addForm = document.getElementById('add-book-form');
  const titleInput = document.getElementById('book-title');
  const pagesInput = document.getElementById('book-pages');
  const formError = document.getElementById('form-error');
  const booksList = document.getElementById('books-list');
  const emptyMessage = document.getElementById('empty-message');

  function render() {
    booksList.innerHTML = '';
    if (books.length === 0) {
      emptyMessage.style.display = 'block';
      return;
    }
    emptyMessage.style.display = 'none';

    books.forEach(book => {
      const li = document.createElement('li');
      li.className = 'book-item';

      const percent = book.pagesRead >= book.totalPages ? 100 : Math.round((book.pagesRead / book.totalPages) * 100);
      const finished = book.pagesRead >= book.totalPages;

      const header = document.createElement('div');
      header.className = 'book-header';
      header.innerHTML = `<span class="book-title">${escapeHtml(book.title)}</span><span class="book-pages">${book.pagesRead} / ${book.totalPages} pages</span>`;

      const progressContainer = document.createElement('div');
      progressContainer.className = 'progress-container';
      const barWrapper = document.createElement('div');
      barWrapper.className = 'progress-bar-wrapper';
      barWrapper.setAttribute('role', 'progressbar');
      barWrapper.setAttribute('aria-valuemin', '0');
      barWrapper.setAttribute('aria-valuemax', '100');
      barWrapper.setAttribute('aria-valuenow', percent);
      barWrapper.setAttribute('aria-label', `Progress for ${book.title}`);
      const bar = document.createElement('div');
      bar.className = 'progress-bar' + (finished ? ' finished' : '');
      bar.style.width = percent + '%';
      barWrapper.appendChild(bar);
      const progressText = document.createElement('span');
      progressText.className = 'progress-text';
      progressText.textContent = percent + '%';
      progressContainer.appendChild(barWrapper);
      progressContainer.appendChild(progressText);

      const logForm = document.createElement('form');
      logForm.className = 'log-form';
      logForm.dataset.bookId = book.id;
      if (finished) {
        const badge = document.createElement('span');
        badge.className = 'finished-badge';
        badge.textContent = '✓ Finished';
        logForm.appendChild(badge);
      } else {
        const logLabel = document.createElement('label');
        logLabel.htmlFor = `log-pages-${book.id}`;
        logLabel.textContent = 'Pages read:';
        const logInput = document.createElement('input');
        logInput.type = 'number';
        logInput.id = `log-pages-${book.id}`;
        logInput.min = '1';
        logInput.max = String(book.totalPages - book.pagesRead);
        logInput.step = '1';
        logInput.placeholder = '0';
        const logBtn = document.createElement('button');
        logBtn.type = 'submit';
        logBtn.className = 'btn log-btn';
        logBtn.textContent = 'Log';
        logForm.appendChild(logLabel);
        logForm.appendChild(logInput);
        logForm.appendChild(logBtn);
        logForm.addEventListener('submit', function(e) {
          e.preventDefault();
          const input = logForm.querySelector('input');
          const val = parseInt(input.value, 10);
          if (isNaN(val) || val <= 0) {
            input.setCustomValidity('Enter a positive number');
            input.reportValidity();
            return;
          }
          input.setCustomValidity('');
          book.pagesRead = Math.min(book.pagesRead + val, book.totalPages);
          render();
        });
      }

      li.appendChild(header);
      li.appendChild(progressContainer);
      li.appendChild(logForm);
      booksList.appendChild(li);
    });
  }

  function escapeHtml(str) {
    const div = document.createElement('div');
    div.textContent = str;
    return div.innerHTML;
  }

  addForm.addEventListener('submit', function(e) {
    e.preventDefault();
    formError.textContent = '';
    const title = titleInput.value.trim();
    const pages = parseInt(pagesInput.value, 10);

    if (!title) {
      formError.textContent = 'Please enter a book title.';
      titleInput.focus();
      return;
    }
    if (isNaN(pages) || pages <= 0) {
      formError.textContent = 'Page count must be a positive number.';
      pagesInput.focus();
      return;
    }

    books.push({ id: nextId++, title, totalPages: pages, pagesRead: 0 });
    titleInput.value = '';
    pagesInput.value = '';
    titleInput.focus();
    render();
  });

  render();
})();
